public static String packApples(int[] weights, int sizeA, int sizeB, int sizeC) {
    int a = 0, b = 0, c = 0;
    int i = 0;
    while (a < sizeA && b < sizeB && c < sizeC) {
        if (weights[i] > 350) {
            a++;
        } else if (weights[i] > 250) {
            b++;
        } else {
            c++;
        }
        i++;
    }
    return a + " " + b + " " + c;
}

